_fonts = {}


def F(path, size):
    key = (path, size)
    if key not in _fonts:
        _fonts[key] = ImageFont.truetype(path, size)
    return _fonts[key]


WARNINGS = []


def wrap(text, font, width):
    """Greedy word wrap to pixel width; returns list of lines."""
    words = text.split()
    lines, cur = [], ""
    for w in words:
        trial = (cur + " " + w).strip()
        if font.getlength(trial) <= width:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def block(d, x, y, text, font, fill, width, max_lines, line_h, tag):
    """Draw wrapped text; warn + truncate if it needs more than max_lines."""
    lines = wrap(text, font, width)
    if len(lines) > max_lines:
        WARNINGS.append(f"{tag}: {len(lines)} lines, only {max_lines} fit: {text[:60]!r}")
        lines = lines[:max_lines]
    for i, ln in enumerate(lines):
        d.text((x, y + i * line_h), ln, font=font, fill=fill)
    return y + len(lines) * line_h


# ---------------------------------------------------------------- scenes
def scene(d, box, kind):
    """Flat scene in box (x0, y0, x1, y1). No text. kind selects the motif."""
    x0, y0, x1, y1 = box
    w, h = x1 - x0, y1 - y0
    if kind == "summit":  # three leaders seated at a negotiation table (BIG)
        d.rectangle(box, fill=(52, 74, 96))  # panelled wall
        d.rectangle([x0, y0 + 10, x1, y0 + 14], fill=(190, 160, 110))  # gold trim
        d.rectangle([x0, y1 - 30, x1, y1], fill=(96, 62, 40))  # table
        d.rectangle([x0, y1 - 30, x1, y1 - 25], fill=(150, 105, 70))  # table edge
        # papers on the table
        d.rectangle([x0 + w // 2 - 46, y1 - 24, x0 + w // 2 - 24, y1 - 17], fill=(240, 240, 230))
        d.rectangle([x0 + w // 2 + 26, y1 - 24, x0 + w // 2 + 48, y1 - 17], fill=(240, 240, 230))
        for j, (fx, suit, skin, hair) in enumerate([
                (0.20, (30, 50, 90), (232, 196, 160), (200, 200, 200)),   # grey hair, navy suit
                (0.50, (45, 45, 50), (220, 180, 145), (40, 32, 28)),      # dark hair, charcoal suit
                (0.80, (120, 40, 40), (210, 170, 140), (180, 170, 150))]):  # light hair, burgundy suit
            cx = x0 + int(w * fx)
            cy = y1 - 58
            # shoulders (big trapezoid)
            d.polygon([(cx - 36, y1 - 28), (cx - 20, y1 - 50),
                       (cx + 20, y1 - 50), (cx + 36, y1 - 28)], fill=suit)
            # shirt + tie
            d.polygon([(cx - 9, y1 - 48), (cx + 9, y1 - 48), (cx, y1 - 29)],
                      fill=(240, 240, 235))
            d.rectangle([cx - 3, y1 - 46, cx + 3, y1 - 29], fill=(160, 40, 40))
            # head + hair (big, reads at full-page size)
            d.ellipse([cx - 17, cy - 17, cx + 17, cy + 17], fill=skin)
            d.pieslice([cx - 17, cy - 17, cx + 17, cy + 17], start=180, end=360, fill=hair)
            # nameplate on the table front
            d.rectangle([cx - 12, y1 - 21, cx + 12, y1 - 12], fill=(220, 215, 195))
    elif kind == "gta":  # sports car drifting on a night street (BIG)
        d.rectangle(box, fill=(38, 22, 60))  # dusk purple sky
        d.ellipse([x0 + 22, y0 + 8, x0 + 62, y0 + 48], fill=(240, 140, 60))  # low sun
        for sx, sy in [(0.30, 0.18), (0.55, 0.10), (0.78, 0.22), (0.92, 0.12)]:
            d.ellipse([x0 + int(w * sx) - 2, y0 + int(h * sy) - 2,
                       x0 + int(w * sx) + 2, y0 + int(h * sy) + 2], fill=(220, 210, 240))
        # road
        d.rectangle([x0, y1 - 36, x1, y1], fill=(28, 28, 32))
        d.line([(x0, y1 - 36), (x1, y1 - 36)], fill=(200, 170, 90), width=2)
        # skid marks trailing from the rear wheel
        d.line([(x0 + 20, y1 - 6), (x0 + 58, y1 - 12), (x0 + 92, y1 - 18), (x0 + 118, y1 - 24)],
               fill=(10, 10, 12), width=5)
        d.line([(x0 + 28, y1 - 14), (x0 + 62, y1 - 19), (x0 + 96, y1 - 24), (x0 + 120, y1 - 29)],
               fill=(10, 10, 12), width=4)
        # tyre smoke at the rear wheel (big puffs)
        for sx, sy, sr in [(106, -58, 12), (88, -66, 15), (68, -58, 10), (52, -68, 8)]:
            d.ellipse([x0 + sx - sr, y1 + sy - sr, x0 + sx + sr, y1 + sy + sr],
                      fill=(205, 200, 195))
        # wheels (big)
        rw = (x0 + 118, y1 - 44)
        fw = (x0 + 228, y1 - 44)
        for cx, cy in (rw, fw):
            d.ellipse([cx - 14, cy - 14, cx + 14, cy + 14], fill=(12, 12, 14))
            d.ellipse([cx - 6, cy - 6, cx + 6, cy + 6], fill=(170, 170, 175))
        # body: low wedge, nose sloping down to the right
        d.polygon([(rw[0] - 28, y1 - 46), (rw[0] - 20, y1 - 66), (rw[0] + 22, y1 - 70),
                   (fw[0] - 10, y1 - 70), (fw[0] + 28, y1 - 58), (fw[0] + 34, y1 - 46)],
                  fill=(222, 64, 38))
        # cabin glass (light, so it reads against the dark sky)
        d.polygon([(rw[0] + 14, y1 - 66), (rw[0] + 34, y1 - 80), (fw[0] - 18, y1 - 80),
                   (fw[0] - 2, y1 - 66)], fill=(120, 150, 190))
        d.line([(rw[0] + 38, y1 - 77), (fw[0] - 22, y1 - 77)], fill=(210, 225, 240), width=3)
        # door shut-line + side skirt for definition
        d.line([(rw[0] + 58, y1 - 66), (rw[0] + 58, y1 - 47)], fill=(140, 42, 26), width=3)
        d.rectangle([rw[0] - 26, y1 - 50, fw[0] + 32, y1 - 46], fill=(160, 46, 28))
        # headlight + beam
        d.ellipse([fw[0] + 28, y1 - 58, fw[0] + 36, y1 - 50], fill=(255, 240, 180))
        d.polygon([(fw[0] + 34, y1 - 54), (x1 - 4, y1 - 60), (x1 - 4, y1 - 46),
                   (fw[0] + 34, y1 - 48)], fill=(255, 240, 180))
        # tail light
        d.rectangle([rw[0] - 28, y1 - 58, rw[0] - 22, y1 - 50], fill=(255, 60, 50))
        # speed lines
        for ly in (0.50, 0.64):
            yy = y0 + int(h * ly)
            d.line([(x0 + 8, yy), (x0 + 44, yy)], fill=(200, 190, 220), width=3)
    elif kind == "ipo":  # candlestick price chart, like Junior's reference:
        # dark trading screen, green/red candles with wicks, volume bars below
        d.rectangle(box, fill=(22, 26, 40))  # dark navy background
        GREEN = (16, 200, 130)
        RED = (235, 75, 95)
        # faint horizontal gridlines across the candle area
        top, bot = y0 + 5, y0 + 66
        for gy in (top + 16, top + 33, top + 50):
            d.line([(x0 + 4, gy), (x1 - 4, gy)], fill=(44, 50, 70), width=1)
        # price series: (open, close, high, low) — IPO debut day: choppy open,
        # then a strong climb to a high close
        candles = [
            (55, 48, 58, 44), (48, 50, 52, 44), (50, 45, 51, 42),
            (45, 47, 49, 40), (47, 42, 48, 38), (42, 46, 48, 40),
            (46, 56, 58, 45), (56, 53, 58, 50), (53, 62, 64, 52),
            (62, 72, 74, 60), (72, 80, 84, 70), (80, 74, 82, 70),
            (74, 70, 76, 66), (70, 78, 80, 68), (78, 84, 86, 76),
        ]
        volumes = [30, 18, 22, 26, 20, 16, 34, 20, 26, 30, 36, 24, 20, 28, 32]
        lo, hi = 36, 88  # price scale
        n = len(candles)
        slot = (w - 12) / n
        bw = 12  # candle body width

        def py(p):
            return bot - (p - lo) / (hi - lo) * (bot - top)

        closes = []
        for i, (o, c, h, l) in enumerate(candles):
            cx = x0 + 6 + slot * i + slot / 2
            col = GREEN if c >= o else RED
            # wick
            d.line([(cx, py(h)), (cx, py(l))], fill=col, width=2)
            # body
            d.rectangle([cx - bw / 2, py(max(o, c)), cx + bw / 2, py(min(o, c))],
                        fill=col)
            closes.append((cx, py(c)))
        # thin gold MA line through the closes, like the reference app
        d.line(closes, fill=(240, 200, 80), width=2, joint="curve")
        # volume bars below
        vtop = y0 + 70
        vbot = y1 - 5
        d.line([(x0 + 4, vtop - 2), (x1 - 4, vtop - 2)], fill=(44, 50, 70), width=1)
        vmax = max(volumes)
        for i, (o, c, h, l) in enumerate(candles):
            cx = x0 + 6 + slot * i + slot / 2
            col = GREEN if c >= o else RED
            vh = max(3, volumes[i] / vmax * (vbot - vtop))
            d.rectangle([cx - bw / 2, vbot - vh, cx + bw / 2, vbot], fill=col)
    elif kind == "court":  # pillars + pediment
        d.rectangle(box, fill=(214, 205, 182))
        d.polygon([(x0 + w // 2 - 60, y0 + 8), (x0 + w // 2 + 60, y0 + 8),
                   (x0 + w // 2, y0 + 26)], fill=(120, 110, 92))
        for i in range(4):
            px = x0 + 28 + i * 52
            d.rectangle([px, y0 + 30, px + 16, y1 - 8], fill=(240, 235, 220))
            d.rectangle([px - 3, y0 + 28, px + 19, y0 + 32], fill=(240, 235, 220))
        d.rectangle([x0, y1 - 8, x1, y1], fill=(120, 110, 92))
    elif kind == "climate":  # sun + hills
        d.rectangle(box, fill=(238, 214, 150))
        d.ellipse([x0 + w - 52, y0 + 8, x0 + w - 18, y0 + 42], fill=(224, 122, 44))
        d.polygon([(x0, y1), (x0 + 70, y0 + 34), (x0 + 150, y1)], fill=(120, 150, 90))
        d.polygon([(x0 + 110, y1), (x0 + 200, y0 + 44), (x1, y1)], fill=(90, 125, 70))
    elif kind == "storm":  # spiral + rain
        d.rectangle(box, fill=(36, 84, 96))
        cx, cy = x0 + w // 2, y0 + h // 2 + 2
