# ---------------------------------------------------------------- map
def draw_map(d, x0, y0, x1, y1):
    d.rectangle([x0, y0, x1, y1], fill=NAVY)
    d.text((x0 + 10, y0 + 8), "WHERE IT HAPPENED", font=F(SANS_B, 13), fill=(240, 240, 235))
    mx, my = x0 + 4, y0 + 30
    mw, mh = (x1 - x0) - 8, 240
    # real world map (Mercator, lat -60..85) centred in the 280x268 box
    ox = mx
    oy = my + (mh - MAP_H) // 2
    # graticule: every 30 deg lon, and lat -60/-30/0/30/60
    grat = (58, 88, 112)
    for i in range(13):
        gx = ox + i * MAP_W / 12
        d.line([(gx, oy), (gx, oy + MAP_H)], fill=grat, width=1)

    def _my(lat):
        return math.log(math.tan(math.pi / 4 + math.radians(lat) / 2))
    _yt, _yb = _my(85), _my(-60)
    for lat in (-60, -30, 0, 30, 60):
        gy = oy + (_yt - _my(lat)) / (_yt - _yb) * MAP_H
        d.line([(ox, gy), (ox + MAP_W, gy)], fill=grat, width=1)
    # land (real coastlines)
    for poly in MAP_POLYS:
        pts = [(ox + px, oy + py) for px, py in poly]
        d.polygon(pts, fill=LAND, outline=(190, 170, 115))
    # ocean labels
    oc = (150, 180, 200)
    f = F(SANS_B, 8)
    for label, lx, ly in [
        ("PACIFIC OCEAN", 40, 165),
        ("ATLANTIC", 125, 165),
        ("INDIAN OCEAN", 196, 165),
        ("ARCTIC OCEAN", 40, 22),
        ("SOUTHERN OCEAN", 140, 188),
    ]:
        d.text((ox + lx, oy + ly), label, font=f, fill=oc, anchor="ma")
    dots = [  # (num, x, y) world-box coords, real lon/lat (nudged where crowded)
        (1, 222, 116), (2, 78, 102), (3, 96, 112), (4, 136, 86), (5, 170, 108),
        (6, 207, 123), (7, 164, 90), (8, 236, 128), (9, 72, 122), (10, 125, 73),
        (11, 148, 100), (12, 173, 126), (13, 150, 116),
    ]
    for n, px, py in dots:
        cx, cy = ox + px, oy + py
        d.ellipse([cx - 8, cy - 8, cx + 8, cy + 8], fill=RED, outline=(240, 240, 235), width=1)
        t = str(n)
        tw = F(SANS_B, 10).getlength(t)
        d.text((cx - tw / 2, cy - 7), t, font=F(SANS_B, 10), fill=(255, 255, 255))
    grey = [  # real brief locations
        (72, 90), (58, 128), (88, 131), (87, 153), (196, 112),
        (249, 110), (169, 141), (256, 169), (272, 170),
    ]
    for px, py in grey:
        cx, cy = ox + px, oy + py
        d.ellipse([cx - 3, cy - 3, cx + 3, cy + 3], fill=(160, 160, 150))
    cap = ("Red numbers mark stories 1–13; grey dots mark the briefs below.")
    block(d, x0 + 10, y0 + 272, cap, F(SANS, 10), (225, 225, 215),
          (x1 - x0) - 20, 2, 13, "map caption")


# ---------------------------------------------------------------- main
def main():
    img = Image.new("RGB", (W, H), BG)
    d = ImageDraw.Draw(img)
    # background: soft vertical gradient + faint paper dots + masthead band
    for yy in range(H):
        t = yy / (H - 1)
        d.line([(0, yy), (W, yy)],
               fill=(int(250 + (238 - 250) * t),
                     int(247 + (230 - 247) * t),
                     int(236 + (210 - 236) * t)))
    for yy in range(14, H, 30):
        for xx in range(14, W, 30):
            d.ellipse([xx - 1, yy - 1, xx + 1, yy + 1], fill=(238, 231, 214))
    d.rectangle([0, 0, W, 96], fill=(242, 236, 220))
    M = 12
    # masthead
    d.text((W // 2, 6), "THE WORLD IN ONE DAY", font=F(SERIF_B, 15),
           fill=RED, anchor="ma")
    # blue line above + red line below the title (Junior: "garis atas bawah
    # warna biru dan merah"), framing just the title so they clear the AI badge
    _tw = F(SERIF_B, 42).getlength("Thursday 19 November 2026")
    _tl0, _tl1 = W // 2 - int(_tw / 2) - 24, W // 2 + int(_tw / 2) + 24
    d.line([(_tl0, 28), (_tl1, 28)], fill=BLUE, width=3)
    d.text((W // 2, 26), "Thursday 19 November 2026", font=F(SERIF_B, 42),
           fill=INK, anchor="ma")
    d.line([(_tl0, 74), (_tl1, 74)], fill=RED, width=3)
    d.text((W // 2, 77), "Three leaders meet in Shenzhen · A court rules on Myanmar · The biggest IPO ever debuts",
           font=F(SERIF_I, 15), fill=RED, anchor="ma")
    # AI logo badge (top-left of the masthead, clear of the centered title)
    lx0, ly0, lx1, ly1 = 14, 12, 78, 76
    d.rounded_rectangle([lx0, ly0, lx1, ly1], radius=12, fill=NAVY)
    d.text(((lx0 + lx1) // 2, (ly0 + ly1) // 2 - 2), "AI", font=F(SANS_B, 30),
           fill=(255, 255, 255), anchor="mm")
    # gold spark at the badge's top-right corner
    sx, sy = lx1 - 2, ly0
    d.polygon([(sx, sy - 9), (sx + 3, sy - 3), (sx + 9, sy), (sx + 3, sy + 3),
               (sx, sy + 9), (sx - 3, sy + 3), (sx - 9, sy), (sx - 3, sy - 3)],
              fill=(212, 175, 55))
    d.text((lx0, ly1 + 4), "AI EDITION", font=F(SANS_B, 9), fill=RED)
    d.line([(M, 96), (W - M, 96)], fill=INK, width=2)
    d.text((W // 2, 100), "THURSDAY'S NEWS · ONE PAGE · 36 STORIES",
           font=F(SANS_B, 12), fill=INK, anchor="ma")
    # continent bar
    total = sum(c for _, _, c in CONTINENTS)
    bx = M
    bar_w = W - 2 * M
    for label, col, n in CONTINENTS:
        wseg = bar_w * n / total
        d.rectangle([bx, 116, bx + wseg, 132], fill=col)
        f = F(SANS_B, 11)
        tw = f.getlength(label)
        if tw <= wseg - 6:
            d.text((bx + wseg / 2, 118), label, font=f, fill=(255, 255, 255), anchor="ma")
        bx += wseg
    # KPI strip
    kpi_y = 134
    col_w = (W - 2 * M) / 6
    for i, (num, cap) in enumerate(KPIS):
        cx = M + i * col_w
        if i:
            d.line([(cx, kpi_y + 4), (cx, kpi_y + 40)], fill=BORDER, width=1)
        fnum = F(SERIF_B, 24)
        tw = fnum.getlength(num)
        d.text((cx + col_w / 2, kpi_y), num, font=fnum, fill=RED, anchor="ma")
        block(d, cx + 6, kpi_y + 24, cap, F(SANS, 9), INK, col_w - 12, 2, 10, f"KPI {num}")
    d.line([(M, 180), (W - M, 180)], fill=INK, width=1)
    # heroes (tall art strips so the three scenes read at full-page size)
    hy, hh = 184, 191
    hw = (W - 2 * M - 12) / 3
    for i, (tag, head, body, kind) in enumerate(HEROES):
        x0 = M + i * (hw + 6)
        x1 = x0 + hw
        d.rectangle([x0, hy, x1, hy + hh], fill=PANEL, outline=BORDER, width=1)
        scene(d, (x0 + 1, hy + 1, x1 - 1, hy + 101), kind)
        d.text((x0 + 8, hy + 105), tag, font=F(SANS_B, 11), fill=RED)
        block(d, x0 + 8, hy + 119, head, F(SERIF_B, 16), INK, hw - 16, 2, 17, f"hero {i+1} head")
        block(d, x0 + 8, hy + 155, body, F(SANS, 11), INK, hw - 16, 3, 12, f"hero {i+1} body")
    # small panels, 2 rows x 5
    pw = (W - 2 * M - 24) / 5
    ph = 116
    for r in range(2):
        for c in range(5):
            idx = r * 5 + c
            tag, head, body, kind = SMALL[idx]
            x0 = M + c * (pw + 6)
            y0 = 379 + r * (ph + 4)
            x1 = x0 + pw
            d.rectangle([x0, y0, x1, y0 + ph], fill=PANEL, outline=BORDER, width=1)
            scene(d, (x0 + 1, y0 + 1, x1 - 1, y0 + 39), kind)
            d.text((x0 + 6, y0 + 42), tag, font=F(SANS_B, 10), fill=RED)
            block(d, x0 + 6, y0 + 55, head, F(SERIF_B, 12), INK, pw - 12, 2, 13, f"panel {idx+4} head")
            block(d, x0 + 6, y0 + 82, body, F(SANS, 10), INK, pw - 12, 2, 12, f"panel {idx+4} body")
    # good news band
    gy0, gy1 = 619, 649
    d.rectangle([M, gy0, W - M, gy1], fill=GOOD_BG, outline=GOOD_LINE, width=1)
    d.text((M + 10, gy0 + 9), "GOOD NEWS TODAY", font=F(SANS_B, 13), fill=GOOD_DARK)
    gx = M + 150
    gw = (W - M - gx - 8) / 3
    for i, item in enumerate(GOOD_NEWS):
        cx = gx + i * gw
        if i:
            d.line([(cx - 6, gy0 + 5), (cx - 6, gy1 - 5)], fill=GOOD_LINE, width=1)
        block(d, cx + 4, gy0 + 9, item, F(SANS, 10), INK, gw - 16, 2, 11, f"good news {i+1}")
    # bottom: map + briefs
    by = 653
    draw_map(d, M, by, 300, 952)
    bx0 = 308
    d.text((bx0, by + 2), "ALSO ON THURSDAY 19 NOVEMBER — 23 MORE STORIES",
           font=F(SANS_B, 13), fill=RED)
    d.line([(bx0, by + 22), (W - M, by + 22)], fill=RED, width=1)
    cols = [BRIEFS[0:8], BRIEFS[8:16], BRIEFS[16:23]]
    col_w = (W - M - bx0 - 16) / 3
    for ci, col in enumerate(cols):
        cx = bx0 + ci * (col_w + 8)
        cy = by + 30
        for place, text in col:
            full = f"{place} — {text}"
            lines = wrap(full, F(SANS, 10), col_w)
            if len(lines) > 3:
                WARNINGS.append(f"brief {place}: {len(lines)} lines, cap 3")
                lines = lines[:3]
            # bold the leading "NN PLACE —" part
            head_txt = place + " — "
            hw_ = F(SANS_B, 10).getlength(head_txt)
            y = cy
            # first line: bold head + rest
            first = lines[0]
            d.text((cx, y), head_txt, font=F(SANS_B, 10), fill=INK)
            rest = first[len(head_txt):] if first.startswith(head_txt) else first
            # wrap() may split the head across lines; handle by re-wrapping body only
            if not first.startswith(head_txt):
                # head alone didn't fit pattern; draw whole first line regular
                d.text((cx, y), first, font=F(SANS, 10), fill=INK)
            else:
                d.text((cx + hw_, y), rest, font=F(SANS, 10), fill=INK)
            for ln in lines[1:]:
                y += 13
                d.text((cx, y), ln, font=F(SANS, 10), fill=INK)
            cy = y + 13 + 7
    # red + green rules at the bottom (Junior: "di bagian bawah merah dan hijau"),
    # framing the footer block, mirroring the title lines
    d.line([(M, 950), (W - M, 950)], fill=RED, width=3)
    # date check box
    d.rectangle([M, 956, W - M, 994], outline=RED, width=2)
    block(d, M + 8, 960, DATE_CHECK, F(SANS, 10), INK, W - 2 * M - 16, 3, 12, "date check")
    # footer
    block(d, M, 998, FOOTER, F(SANS, 9), (80, 80, 75), W - 2 * M, 2, 11, "footer")
    d.line([(M, 1021), (W - M, 1021)], fill=GOOD_LINE, width=2)
    img.save("entry.png", optimize=True)
    print("saved entry.png")
    if WARNINGS:
        print(f"WARNINGS ({len(WARNINGS)}):")
        for w_ in WARNINGS:
            print(" -", w_)
    else:
        print("zero warnings")


if __name__ == "__main__":
    main()
